\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{siunitx}

\title{Hydraulic Accumulator Test Log}
\author{Rig Maintenance Crew}
\date{}

\begin{document}
\maketitle

\section{Bench Setup}
The test bench charges the accumulator from the main pump
and bleeds it through the calibrated orifice. Line pressure
is logged at 1 kHz on channel 3, and the rig is interlocked
against the relief valve at all times.

\section{Limits}
The accumulator is rated at \SI{300}{\mega\pascal}, and the
relief valve is set ten percent below that figure. The pump
motor is rated at \SI{85}{\kilo\watt}, which is ample for
the duty cycle we run; the motor reaches only about two
thirds of its thermal limit during a full charge.

\section{Procedure}
Charge to the working pressure, hold for five minutes, then
bleed through the orifice while recording the decay curve.
Repeat three times and compare the curves; any drift beyond
the band in the calibration sheet triggers a valve check
before the next shift.
\end{document}

